"""Create distinct runoff records from official signed advancement flags and ministry district list."""
from pathlib import Path
from bs4 import BeautifulSoup
import copy,json,re,hashlib,xml.etree.ElementTree as ET
from datetime import datetime,timezone
P=Path('scripts/czech-senate-2026-runoffs');C=Path('.cache/czech-runoffs');baseline=json.loads((P/'pre-import-backup.json').read_text());old={r['id']:r['data'] for r in baseline};root=ET.parse(C/'results.xml').getroot();ns={'n':'http://www.volby.cz/senat/'};stamp=datetime.now(timezone.utc).isoformat(timespec='seconds');register={(r['OBVOD'],r['CKAND']):r for r in json.loads((C/'candidates.json').read_text())['polozky'] if r['PLATNOST']=='A'}
ministry=BeautifulSoup((C/'ministry.html').read_text(),'html.parser');district_numbers={int(n) for n in re.findall(r'Volební obvod č\.\s*(\d+)',ministry.get_text(' ',strip=True))};assert len(district_numbers)==22
sources=[dict(label='Czech Interior Ministry: confirmed runoff districts and polling hours',url='https://mv.gov.cz/volby-referenda/informace-pro-volice-k-ii-kolu-voleb-do-senatu'),dict(label='Czech Statistical Office: official candidate outcomes and runoff counts',url='https://volby.gov.cz/appdata/senat/20261009/odata/vysledky.xml'),dict(label='Czech Statistical Office: candidate register and nominations',url='https://volby.gov.cz/opendata/se2026/json/serk.json')]
records=[];audit=[];skipped=[]
for district in root.findall('n:OBVOD',ns):
 n=int(district.attrib['CISLO']);name=district.attrib['NAZEV'];first=old[f'world-cz-senate-2026-district-{n}-round-1'];adv=[c for c in district.findall('n:KANDIDAT',ns) if c.attrib.get('ZVOLEN_1KOLO')=='2.KOLO'];winners=[c for c in district.findall('n:KANDIDAT',ns) if c.attrib.get('ZVOLEN_1KOLO')=='ZVOLEN']
 if n not in district_numbers:assert len(winners)==1 and not adv;skipped.append(n);continue
 assert len(adv)==2 and not winners,(n,len(adv));e=copy.deepcopy(first);e.update(id=f'world-cz-senate-2026-district-{n}-round-2',title=f'Czechia Senate election — {name} (district {n}) runoff 2026',round='Second round',startDate='2026-10-16',endDate='2026-10-17',status='scheduled',publication='published',precision='day',dateStatus='confirmed',checked='2026-10-16',version=1,resultStatus='not-entered',resultCoverage='complete',turnout=None,totalSeats=1,summary=f'{name} elects one senator in the second round on 16–17 October 2026.',government='',results=[],overviewId='world-calendar-cz-senate-2026-runoff',linkedElectionIds=[first['id'],'world-calendar-cz-senate-2026-runoff','world-czech-senate-2026'],sources=sources,voteBasis='Second-round candidate votes within this electoral district; first-round votes do not carry over',notes='One seat in the 81-member Czech Senate. Only the two candidates officially advanced from the first round appear in this runoff. Votes cast on 9–10 October do not carry over. Polling hours in Europe/Prague (CEST): Friday 16 October, 14:00–22:00; Saturday 17 October, 08:00–14:00. Runoff votes, turnout and winners will be reported only when second-round figures are published. Candidate party membership and the nominating electoral list are distinguished; independent candidates retain their registered nomination. No personal ideology is inferred.',live=dict(enabled=True,reporting=None,unit='precincts reporting',bulletin='Voting takes place on 16–17 October. Polls close at 14:00 CEST on Saturday 17 October. No second-round results have been published; first-round totals are available in the linked record.',updated=stamp))
 firstrows={r['id']:r for r in first['results']};entries=[]
 for candidate in adv:
  a=candidate.attrib;k=int(a['PORADOVE_CISLO']);reg=register[n,k];assert reg['JMENO']==a['JMENO'] and reg['PRIJMENI']==a['PRIJMENI'];row=copy.deepcopy(firstrows[f'cz-senate-2026-{n}-{k}']);assert row.get('advanced') and row['name']==a['JMENO']+' '+a['PRIJMENI'];row.update(id=f'cz-senate-2026-{n}-{k}-round-2',votes=None,share=None,seats=None,previousSeats=None,electoralVotes=None,winner=False,advanced=False);e['results'].append(row);entries.append(dict(candidateNumber=k,name=row['name'],membershipCode=reg['PSTRANA'],nominationCode=reg['VSTRANA'],firstRoundVotes=int(a['HLASY_1KOLO']),firstRoundShare=float(a['HLASY_PROC_1KOLO'])))
 u=district.find("n:UCAST[@KOLO='2']",ns);assert u is not None and int(u.attrib['OKRSKY_ZPRAC'])==0,(n,'Runoff counting has begun; import current results instead')
 records.append(e);audit.append(dict(district=n,name=name,firstRoundId=first['id'],runoffId=e['id'],candidates=entries,runoffPrecinctsReported=0))
assert len(records)==22 and set(skipped)=={12,33,39,48,57}
runoff=copy.deepcopy(old['world-calendar-cz-senate-2026-runoff']);runoff.update(title='Czechia Senate election — second-round overview 2026',checked='2026-10-16',version=runoff['version']+1,totalSeats=22,summary='Twenty-two Senate seats are contested in runoffs on 16–17 October 2026. Five seats were decided in the first round.',notes='This overview covers the 22 district runoffs, not a nationwide party ballot. Each district elects one senator. The five districts decided in the first round—12 Strakonice, 33 Děčín, 39 Trutnov, 48 Rychnov nad Kněžnou and 57 Vyškov—do not vote again. The full Senate has 81 seats, including 54 continuing seats. Runoff candidates and results are recorded separately in the linked district pages. Polling hours in Europe/Prague (CEST): 16 October 14:00–22:00; 17 October 08:00–14:00.',sources=sources,linkedElectionIds=['world-czech-senate-2026']+[e['id'] for e in records],voteBasis='Separate single-member district runoffs; candidate percentages are not combined nationally',live=dict(enabled=False,reporting=None,unit='precincts',bulletin='Runoff coverage is available in the 22 district entries on Live Elections. No second-round results have been published.',updated=stamp))
records.append(runoff)
for name,data in [('records',records),('audit',dict(verifiedAt=stamp,officialXmlTimestamp=root.attrib['DATUM_CAS_GENEROVANI'],runoffDistricts=sorted(district_numbers),decidedInFirstRound=skipped,districts=audit,sources=[dict(file=f,sha256=hashlib.sha256((C/f).read_bytes()).hexdigest()) for f in ['results.xml','candidates.json','ministry.html']]))]:
 (P/(name+'.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
(P/'official-results.xml').write_bytes((C/'results.xml').read_bytes())
print(len(records)-1,'runoff elections;',sum(len(e['results']) for e in records),'candidates; overview updated')
